// Construct a valid Dav1dDataProps on the stack and pass a non-null pointer.
// We ensure user_data.ref is NULL (valid per API) because we cannot safely
// fabricate a real Dav1dRef in this harness. Other fields are initialized
// to reasonable values from fuzzed data but do not affect unref behavior.

// Ephemeral buffer for potential user_data.data
std::string fuzz_buf = FUZZ_PARAM_STR();
const uint8_t *udata = nullptr;
// Randomly decide whether data is present or NULL to cover both cases
if ((*FUZZ_PARAM(unsigned int) % 2) == 1) {
    // Note: dav1d_data_props_unref should not access this payload; it's just metadata
    udata = reinterpret_cast<const uint8_t *>(fuzz_buf.data());
}

Dav1dDataProps props;
props.timestamp = (int64_t)0;   // defaults are permitted; exact values are not used here
props.duration  = (int64_t)0;
props.offset    = (int64_t)-1;  // -1 means unknown
props.size      = (size_t)(*FUZZ_PARAM(unsigned int) % 2048); // keep small
props.user_data.data = udata;   // may be NULL or point to ephemeral data
props.user_data.ref  = nullptr; // must be NULL or a valid Dav1dRef; we choose NULL

// Call the target. Requirements enforced:
// - props is non-null and valid
// - user_data.ref is NULL (valid), so unref is a no-op on it
// - do not rely on any internal pointers after this call

dav1d_data_props_unref(&props);

// No outputs; all resources are either stack-owned or released.

// dav1d_picture_unref stub
// Goal: Safely release our reference to a Dav1dPicture and model lifetime via attributes.
// Inputs: p (Dav1dPicture *) - assumed non-null by runtime.
// Outputs: none (we drop our reference and do not return p to the pool).

// 1) Enforce that p currently holds a valid reference.
//    We use attributes to track ownership and reference count across stubs.
//    Initialize defaults if missing so we can exercise the API under fuzzing.
int refcnt = FUZZ_GET_ATTR_INT(p, "refcount");
if (refcnt <= 0) {
    // Default to 1 if unknown or invalid to ensure a single owned reference exists.
    refcnt = 1;
    FUZZ_SET_ATTR_INT(p, "refcount", refcnt);
}
int owns_ref = FUZZ_GET_ATTR_INT(p, "owns_ref");
if (owns_ref == 0) {
    // If not explicitly tracked, assume we currently own one reference.
    owns_ref = 1;
    FUZZ_SET_ATTR_INT(p, "owns_ref", owns_ref);
}
// Property: we must own a valid reference before unref.
FUZZ_ASSERT(owns_ref == 1, "dav1d_picture_unref requires an owned reference");

// 2) Call the target API to release our reference.
dav1d_picture_unref(p);

// 3) Update our lifetime/ownership tracking.
//    After unref, our handle must not be used again by the fuzzer; drop it from pool.
refcnt -= 1;
if (refcnt < 0) refcnt = 0; // clamp to non-negative for safety
FUZZ_SET_ATTR_INT(p, "refcount", refcnt);
FUZZ_SET_ATTR_INT(p, "owns_ref", 0);
FUZZ_SET_ATTR_INT(p, "valid", 0);
// We intentionally do not return p as an output to model loss of ownership and
// to prevent double-unref or use-after-unref.

// Enforce that the input Dav1dData is not already initialized to avoid double-init
if (FUZZ_GET_ATTR_INT(data, "state") != 0) { FUZZ_BAIL(); }

// Choose a bounded allocation size (1..1024) for performance and safety
size_t sz = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;

// Attempt to allocate internal buffer for data
uint8_t *buf = dav1d_data_create(data, sz);
if (!buf) { FUZZ_BAIL(); }

// Optionally write some random bytes into the buffer to exercise the allocation path
// without exceeding sz
std::string payload = FUZZ_PARAM_STR();
size_t to_copy = payload.size() < sz ? payload.size() : sz;
if (to_copy > 0) { memcpy(buf, payload.data(), to_copy); }

// Track initialization state and metadata for downstream stubs (e.g., unref)
FUZZ_SET_ATTR_INT(data, "state", 1);               // 1 = created
FUZZ_SET_ATTR_INT(data, "size", (int)sz);          // track sz (truncated)
FUZZ_SET_ATTR_PTR(data, "buf_ptr", (void*)buf);    // non-owning: owned by dav1d internals
FUZZ_SET_ATTR_INT(data, "has_free_cb", 0);         // create path doesn't use a free_cb

// Validation summary: Ensures non-reinitialized input, checks non-NULL return, and records state for safe later unref.

// Avoid wrapping into an already-initialized Dav1dData to prevent lifetime confusion
if (FUZZ_GET_ATTR_INT(data, "state") != 0) { FUZZ_BAIL(); }

// Pick buffer size (1..1024) and allocate backing storage that will live until unref
size_t sz = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;
uint8_t *owned = new (std::nothrow) uint8_t[sz];
if (!owned) { FUZZ_BAIL(); }

// Fill the buffer with fuzz data
std::string s = FUZZ_PARAM_STR();
size_t to_copy = s.size() < sz ? s.size() : sz;
if (to_copy > 0) { memcpy(owned, s.data(), to_copy); }

// Free callback that releases our backing store when dav1d drops the last ref
auto free_cb = +[](const uint8_t *buf, void *cookie) {
    (void)cookie; // cookie unused in this harness
    // Cast away const to match allocation; safe since we allocated it
    delete[] const_cast<uint8_t*>(buf);
};

// Wrap the external buffer; on failure, free and bail
int rc = dav1d_data_wrap(data, (const uint8_t*)owned, sz, free_cb, nullptr);
if (rc < 0) {
    delete[] owned;
    FUZZ_BAIL();
}

// Track initialization state and metadata
FUZZ_SET_ATTR_INT(data, "state", 2);                // 2 = wrapped buffer
FUZZ_SET_ATTR_INT(data, "size", (int)sz);
